        rib.setBackground(rbg)
        rlp = FrameLayout.LayoutParams(-2, -2, Gravity.RIGHT | Gravity.TOP)
        rlp.rightMargin = AndroidUtilities.dp(4)
        rlp.topMargin = AndroidUtilities.dp(4)
